/**
 * T232 — the lazy validator of the record schemas.
 *
 * `validatorFor(schemaId)` is keyed by the value a record carries in its
 * `schema` field: the schema id with its major, for example
 * `specstride.lease/1` (F100-FR-048). It resolves the id through the
 * package's own file map (`src/records/schema-map.ts`, generated by
 * `scripts/types.mjs` from `schemas/`) — no `node:` import in the package
 * (plan.md, Constraints) — compiles the schema with the validator of T005
 * (Ajv 8.20.0, draft 2020-12, research.md D-2) at first use, and caches the
 * compiled validator (plan.md, Performance Goals: schemas are compiled
 * lazily, per schema).
 *
 * `validate(schemaId, value)` returns the typed record when it validates,
 * or the list of errors. A record whose `schema` field carries a major the
 * schema does not support is refused with the major found and the major
 * supported (F100-FR-049); an id the package does not hold at all is
 * refused as unknown.
 *
 * Deviation, recorded: the schemas state `format` (for example `date-time`
 * on the timestamps) and the two known formats are registered as
 * always-true, so they are recorded but not asserted. The one validator of
 * D-2 is Ajv without a format package; a format plugin would be a second
 * runtime dependency of `contracts`, which D-2 does not allow.
 */
import { Ajv2020 } from "ajv/dist/2020.js";
import type { ErrorObject, ValidateFunction } from "ajv/dist/2020.js";
import { schemaMap } from "./schema-map.ts";

/** One validation error: the keyword, the path in the record and the message. */
export type SchemaError = {
  keyword: string;
  path: string;
  message: string;
};

/** The result of `validate`: the typed record, or the list of errors. */
export type Validated<T> = { ok: true; record: T } | { ok: false; errors: SchemaError[] };

/** A schema id the package does not hold at all (F100-FR-049). */
export class UnknownSchemaError extends Error {
  constructor(schemaId: string) {
    super(`unknown schema id "${schemaId}": the package holds no schema for it (F100-FR-049)`);
    this.name = "UnknownSchemaError";
  }
}

/** A schema id with a major other than the one the schema supports (F100-FR-049). */
export class UnsupportedMajorError extends Error {
  readonly schemaId: string;
  readonly majorFound: string;
  readonly majorsSupported: string[];

  constructor(schemaId: string, majorFound: string, majorsSupported: string[]) {
    super(
      `refused: the major found is ${majorFound}, the major supported is ` +
        `${majorsSupported.join(" or ")} (schema id "${schemaId}", F100-FR-049)`,
    );
    this.name = "UnsupportedMajorError";
    this.schemaId = schemaId;
    this.majorFound = majorFound;
    this.majorsSupported = majorsSupported;
  }
}

type ParsedId = { base: string; major: string; part: string | undefined };

/**
 * Split a schema id into base, major and part.
 * `specstride.lease/1` -> base `specstride.lease`, major `1`;
 * `specstride.lease/1:owner` -> base `specstride.lease`, major `1`, part `owner`;
 * `specstride-overlay/v1` -> base `specstride-overlay`, major `v1` (an id that
 * keeps its as-is name, contracts/README.md, "The `$id` of a schema file").
 */
function parseId(schemaId: string): ParsedId | undefined {
  const slash = schemaId.indexOf("/");
  if (slash <= 0) return undefined;
  const base = schemaId.slice(0, slash);
  const rest = schemaId.slice(slash + 1);
  const colon = rest.indexOf(":");
  if (colon < 0) return { base, major: rest, part: undefined };
  return { base, major: rest.slice(0, colon), part: rest.slice(colon + 1) };
}

/** The majors the map supports, grouped by base and part. */
function supportedMajors(): Map<string, Set<string>> {
  const groups = new Map<string, Set<string>>();
  for (const id of Object.keys(schemaMap)) {
    const parsed = parseId(id);
    if (!parsed) continue;
    const key = `${parsed.base}\u0000${parsed.part ?? ""}`;
    const majors = groups.get(key) ?? new Set<string>();
    majors.add(parsed.major);
    groups.set(key, majors);
  }
  return groups;
}

/** The Ajv instance of the package: one per process, created at first use. */
let instance: Ajv2020 | undefined;

function validator(): Ajv2020 {
  if (instance) return instance;
  const ajv = new Ajv2020({ strict: false, allErrors: true });
  // The known formats are recorded but not asserted (deviation, above).
  ajv.addFormat("date", true);
  ajv.addFormat("date-time", true);
  instance = ajv;
  return ajv;
}

type Compiled = { schemaId: string; validate: ValidateFunction };

const cache = new Map<string, Compiled>();

/**
 * The compiled validator of the schema id, keyed by the value a record
 * carries in its `schema` field. Compiles at first use, caches afterwards.
 * Throws `UnknownSchemaError` or `UnsupportedMajorError` when the id is not
 * a schema of this package (F100-FR-049).
 */
export function validatorFor(schemaId: string): Compiled {
  const hit = cache.get(schemaId);
  if (hit) return hit;
  const schema = schemaMap[schemaId];
  if (schema === undefined) {
    const parsed = parseId(schemaId);
    if (parsed) {
      const majors = supportedMajors().get(`${parsed.base}\u0000${parsed.part ?? ""}`);
      if (majors !== undefined && !majors.has(parsed.major)) {
        throw new UnsupportedMajorError(schemaId, parsed.major, [...majors].sort());
      }
    }
    throw new UnknownSchemaError(schemaId);
  }
  const compiled = validator().compile(schema as never);
  const entry: Compiled = { schemaId, validate: compiled };
  cache.set(schemaId, entry);
  return entry;
}

function errorsOf(schemaId: string, errors: ErrorObject[] | null | undefined): SchemaError[] {
  return (errors ?? []).map((error) => ({
    keyword: error.keyword,
    path: error.instancePath === "" ? "(record)" : error.instancePath,
    message: `${error.message ?? error.keyword} (schema id "${schemaId}")`,
  }));
}

/**
 * Validate a record. With one argument, the record is validated against
 * the schema id it carries in its `schema` field (F100-FR-048); with two,
 * against the schema id given. Returns the typed record when it validates,
 * or the list of errors — including the refusal of a major the schema does
 * not support and of an id the package does not hold (F100-FR-049).
 */
export function validate<T = Record<string, unknown>>(record: unknown): Validated<T>;
export function validate<T = Record<string, unknown>>(
  schemaId: string,
  value: unknown,
): Validated<T>;
export function validate<T = Record<string, unknown>>(
  ...args: [unknown] | [string, unknown]
): Validated<T> {
  if (args.length === 1) {
    const record = args[0];
    const carried =
      typeof record === "object" && record !== null
        ? (record as { schema?: unknown }).schema
        : undefined;
    if (typeof carried !== "string") {
      return {
        ok: false,
        errors: [
          {
            keyword: "missing-schema",
            path: "/schema",
            message: "the record carries no schema id in its `schema` field (F100-FR-048)",
          },
        ],
      };
    }
    return validate<T>(carried, record);
  }
  const [schemaId, value] = args;
  let compiled: Compiled;
  try {
    compiled = validatorFor(schemaId);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const keyword = err instanceof UnknownSchemaError ? "unknown-schema" : "different-major";
    return { ok: false, errors: [{ keyword, path: "/schema", message }] };
  }
  // The `schema` field is the identity of the record (F100-FR-048): where the
  // schema declares it, a record that names a different id is refused
  // (F100-FR-049), with the major found and the major supported.
  //
  // One record declares the field as a constant without its major: the event
  // envelope of annex X §X.1 carries `schema: "specstride.event"` and its
  // major in `v`. The value the field must carry is therefore read from the
  // schema itself: the constant its description names, else the schema id.
  const schemaObj = schemaMap[schemaId] as
    { properties?: { schema?: { description?: string } } } | undefined;
  const declared = schemaObj?.properties?.schema;
  const constant = /^The constant `([^`]+)`$/.exec(String(declared?.description ?? ""))?.[1];
  const expected = constant ?? schemaId;
  if (
    schemaObj !== undefined &&
    schemaObj.properties !== undefined &&
    "schema" in schemaObj.properties &&
    typeof value === "object" &&
    value !== null &&
    typeof (value as { schema?: unknown }).schema === "string" &&
    (value as { schema?: unknown }).schema !== expected
  ) {
    const found = String((value as { schema?: unknown }).schema);
    const parsed = parseId(found);
    const support = parseId(schemaId);
    const foundMajor = parsed ? parsed.major : found;
    const supportedMajor = support ? support.major : schemaId;
    return {
      ok: false,
      errors: [
        {
          keyword: "different-major",
          path: "/schema",
          message:
            `refused: the major found is ${foundMajor}, the major supported is ` +
            `${supportedMajor} (schema id "${found}", F100-FR-049)`,
        },
      ],
    };
  }
  if (compiled.validate(value)) return { ok: true, record: value as T };
  return { ok: false, errors: errorsOf(schemaId, compiled.validate.errors) };
}
